const $=id=>document.getElementById(id),storageKey='kotoba-practice-v1';let history={};try{const saved=JSON.parse(localStorage.getItem(storageKey)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))history=saved}catch(e){$('save-note').textContent='Không thể đọc tiến độ đã lưu. Bạn vẫn có thể luyện trong phiên này.'}
let queue=[],index=0,answered=false,revealed=false,wrong=[],correct=0,completed=0;
const taskKey=t=>t.v.word+'|'+t.v.kana+'|'+t.form;
function normalizeAnswer(s){return s.normalize('NFKC').replace(/[\u30a1-\u30f6]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60)).replace(/[\s\u200b]/g,'')}
function accepted(t,input){const n=normalizeAnswer(input);return [conjugate(t.v)[t.form],conjugate(t.v,t.v.kana)[t.form]].some(s=>normalizeAnswer(s)===n)}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function stats(){const valid=[];let seen=0,pairs=0,groupCount=0;for(const v of verbs){let found=false;for(const form of ['vocab','group',...columns.map(c=>c[0])]){const record=history[taskKey({v,form})];if(record&&typeof record.ok==='boolean'){found=true;valid.push(record);if(form==='group')groupCount++;else if(form!=='vocab')pairs++}}if(found)seen++}$('group-count').textContent=groupCount+' / '+verbs.length;$('seen').textContent=seen+' / '+verbs.length;$('pairs').textContent=pairs+' / '+verbs.length*columns.length;$('accuracy').textContent=valid.length?Math.round(valid.filter(r=>r.ok).length/valid.length*100)+'%':'—'}
function save(t,ok){history[taskKey(t)]={ok,at:Date.now()};try{localStorage.setItem(storageKey,JSON.stringify(history))}catch(e){$('save-note').textContent='Trình duyệt không lưu được tiến độ. Kết quả chỉ được giữ trong phiên này.'}stats()}
$('study-forms').innerHTML=columns.map(c=>`<label><input type="checkbox" name="study-form" value="${c[0]}" ${['masu','nai','te','ta'].includes(c[0])?'checked':''}> ${c[1]}<small>${c[2]}</small></label>`).join('');
function getPool(){const mode=document.querySelector('input[name="mode"]:checked').value,groups=[...document.querySelectorAll('input[name="study-group"]:checked')].map(i=>+i.value),forms=[...document.querySelectorAll('input[name="study-form"]:checked')].map(i=>i.value),pool=[];for(const v of verbs.filter(v=>groups.includes(v.group))){if(mode==='vocab'||mode==='mixed')pool.push({v,form:'vocab'});if(mode==='group'||mode==='mixed')pool.push({v,form:'group'});if(mode==='forms'||mode==='mixed')for(const form of forms)pool.push({v,form})}return {mode,groups,forms,pool}}
function updateSetup(){const {mode,pool}=getPool();$('forms-field').disabled=mode==='vocab'||mode==='group';$('forms-field').style.opacity=(mode==='vocab'||mode==='group')?'.45':'1';$('pool-info').textContent=pool.length+' câu trong phạm vi đã chọn';$('setup-error').textContent=''}
$('setup').addEventListener('change',updateSetup);$('basic-forms').onclick=()=>{document.querySelectorAll('[name="study-form"]').forEach(i=>i.checked=['masu','nai','te','ta'].includes(i.value));updateSetup()};$('all-forms').onclick=()=>{document.querySelectorAll('[name="study-form"]').forEach(i=>i.checked=true);updateSetup()};
function begin(tasks){queue=tasks;index=0;answered=false;revealed=false;wrong=[];correct=0;completed=0;$('setup').hidden=true;$('results').hidden=true;$('session').hidden=false;showQuestion();$('session').scrollIntoView({behavior:'smooth',block:'start'})}
$('start').onclick=()=>{const {mode,groups,forms,pool}=getPool();if(!groups.length){$('setup-error').textContent='Hãy chọn ít nhất một nhóm động từ.';return}if((mode==='forms'||mode==='mixed')&&!forms.length){$('setup-error').textContent='Hãy chọn ít nhất một thể muốn luyện.';return}shuffle(pool);if($('order').value==='weak'){const rank=t=>{const h=history[taskKey(t)];return h&&typeof h.ok==='boolean'?(h.ok?2:0):1};pool.sort((a,b)=>rank(a)-rank(b))}const n=$('length').value==='all'?pool.length:+$('length').value;begin(pool.slice(0,n))};
function showQuestion(){answered=false;revealed=false;const t=queue[index],v=t.v,isVocab=t.form==='vocab',isGroup=t.form==='group',col=columns.find(c=>c[0]===t.form);$('position').textContent=`Câu ${index+1} / ${queue.length}`;$('score').textContent=`Đúng / nhớ: ${correct}`;$('bar').value=index/queue.length*100;$('group-choices').hidden=!isGroup;groupButtons.forEach(b=>b.disabled=false);$('question-type').textContent=isGroup?'XÁC ĐỊNH NHÓM ĐỘNG TỪ':isVocab?'THẺ GHI NHỚ · NHÓM '+['','I','II','III'][v.group]:'CHIA ĐỘNG TỪ · NHÓM '+['','I','II','III'][v.group];$('prompt').textContent=isGroup?'Động từ này thuộc nhóm nào?':isVocab?'Bạn nhớ cách đọc và nghĩa của từ này không?':`Chuyển sang ${col[1]} · ${col[2]}`;$('word').textContent=v.word;$('hint').textContent=isVocab?'Tự trả lời trước khi lật thẻ.':v.kana+' · '+v.meaning;$('answer-form').hidden=isVocab||isGroup;$('reveal').hidden=!isVocab;$('skip').hidden=isVocab;$('answer').value='';$('answer').setCustomValidity('');$('answer').disabled=false;$('check').disabled=false;$('feedback').hidden=true;$('self-rating').hidden=true;$('next').hidden=true;$('reference').hidden=true;$('reference').open=false;$('session-note').textContent=isGroup?'Chọn một nhóm để xem đáp án và cách ghi nhớ. Các động từ đuôi る có thể thuộc nhóm I hoặc II.':'Gõ bằng bàn phím tiếng Nhật. Chấp nhận kanji hoặc kana; không chấm romaji. Với thẻ từ vựng, hãy tự đánh giá sau khi lật thẻ.';if(isGroup)groupButtons[0].focus({preventScroll:true});else if(!isVocab)$('answer').focus({preventScroll:true});else $('reveal').focus({preventScroll:true})}
function showReference(t){const f=conjugate(t.v),r=conjugate(t.v,t.v.kana);$('reference-content').innerHTML=columns.map(c=>`<div><small>${c[1]} · ${c[2]}</small><b lang="ja">${f[c[0]]}</b><span lang="ja">${r[c[0]]}</span></div>`).join('');$('reference').hidden=false}
function finishAnswer(ok){if(answered)return;answered=true;const t=queue[index];completed++;if(ok)correct++;else wrong.push(t);save(t,ok);$('self-rating').hidden=true;$('answer').disabled=true;$('check').disabled=true;$('skip').hidden=true;$('next').hidden=false;$('next').textContent=index===queue.length-1?'Xem kết quả →':'Câu tiếp theo →';$('score').textContent=`Đúng / nhớ: ${correct}`;$('bar').value=completed/queue.length*100;showReference(t);$('next').focus({preventScroll:true})}
function showSolution(ok,skipped=false){if(queue[index].form==='group'){showGroupSolution(ok,skipped);return;}const t=queue[index],v=t.v,f=conjugate(v)[t.form],kana=conjugate(v,v.kana)[t.form];$('feedback').className='feedback'+(ok?'':' wrong');$('feedback').innerHTML=`<b>${ok?'Chính xác!':skipped?'Cùng ghi nhớ đáp án này nhé.':'Chưa đúng. Đáp án là:'}</b><div class="solution" lang="ja">${f}</div><small lang="ja">${kana}</small><small>${v.word} · ${v.meaning}</small>`;$('feedback').hidden=false;finishAnswer(ok)}
let composing=false;$('answer').addEventListener('compositionstart',()=>composing=true);$('answer').addEventListener('compositionend',()=>composing=false);$('answer').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.isComposing||e.keyCode===229))e.preventDefault()});$('answer-form').onsubmit=e=>{e.preventDefault();if(answered||composing)return;if(!$('answer').value.trim()){$('answer').setCustomValidity('Nhập đáp án hoặc bấm “Chưa nhớ”.');$('answer').reportValidity();return}showSolution(accepted(queue[index],$('answer').value))};$('answer').oninput=()=>{$('answer').setCustomValidity('')};$('skip').onclick=()=>{if(!answered)showSolution(false,true)};
$('reveal').onclick=()=>{if(revealed)return;revealed=true;const v=queue[index].v;$('feedback').className='feedback';$('feedback').innerHTML=`<div class="solution" lang="ja">${v.kana}</div><p>${v.meaning}</p>`;$('feedback').hidden=false;$('reveal').hidden=true;$('self-rating').hidden=false;$('remembered').focus({preventScroll:true})};$('forgot').onclick=()=>finishAnswer(false);$('remembered').onclick=()=>finishAnswer(true);$('next').onclick=()=>{if(!answered)return;index++;if(index>=queue.length)finishSession();else showQuestion()};
function finishSession(){$('session').hidden=true;$('results').hidden=false;$('result-text').textContent=`Bạn đã trả lời ${completed} / ${queue.length} câu: ${correct} câu đúng hoặc đã nhớ, ${wrong.length} câu cần ôn lại.`;$('retry').hidden=!wrong.length;$('mistakes').innerHTML=wrong.length?'<h3>Các câu cần ôn lại</h3>'+wrong.map(t=>{if(t.form==='group')return `<article><div><b lang="ja">${t.v.word}</b><small>Xác định nhóm</small></div><div>${groupLabel(t.v.group)}<small>${t.v.kana} · ${t.v.meaning}</small></div></article>`;const vocab=t.form==='vocab',c=columns.find(c=>c[0]===t.form);return `<article><div><b lang="ja">${t.v.word}</b><small>${vocab?'Cách đọc & nghĩa':c[1]+' · '+c[2]}</small></div><div lang="ja">${vocab?t.v.kana:conjugate(t.v)[t.form]}<small>${vocab?t.v.meaning:conjugate(t.v,t.v.kana)[t.form]}</small></div></article>`}).join(''):completed?'<p>Bạn đã nhớ đúng tất cả câu vừa trả lời. Tiếp tục với những từ chưa học nhé!</p>':'';$('results').scrollIntoView({behavior:'smooth',block:'start'})}

const groupButtons=[$('group-one'),$('group-two'),$('group-three')];
function groupLabel(n){return ['','Nhóm I · Godan','Nhóm II · Ichidan','Nhóm III · Bất quy tắc'][n]}
function groupExplanation(v){
 if(v.group===3)return v.kana==='くる'?'来る（くる）là động từ bất quy tắc: 来ます（きます）, 来ない（こない）.':v.kana==='する'?'する là động từ bất quy tắc: します・しない・して.':'Cụm này kết thúc bằng する và chia theo する: '+conjugate(v).masu+'・'+conjugate(v).te+'。';
 if(v.group===2)return 'Động từ nhóm II: bỏ る rồi thêm đuôi, ví dụ '+conjugate(v).masu+'・'+conjugate(v).te+'。'+(['着る','借りる','見る','いる','起きる','降りる','浴びる'].includes(v.word)?' Hãy ghi nhớ từ này thuộc nhóm II.':'');
 return (v.kana.endsWith('る')?'Dù kết thúc bằng る, từ này thuộc nhóm I. Trước ます, る đổi thành り: ':'Nhóm I: đổi âm cuối sang hàng い trước ます: ')+conjugate(v).masu+'。'+(v.word==='切る'?' Phân biệt 切る（きる, cắt）→ 切ります với 着る（きる, mặc）→ 着ます (nhóm II).':v.word==='要る'?' Phân biệt 要る（いる, cần）→ 要ります với いる（tồn tại）→ います (nhóm II).':'')
}
function showGroupSolution(ok,skipped=false){if(answered)return;const v=queue[index].v;groupButtons.forEach(b=>b.disabled=true);$('feedback').className='feedback'+(ok?'':' wrong');$('feedback').innerHTML=`<b>${ok?'Chính xác!':skipped?'Cùng ghi nhớ nhé.':'Chưa đúng. Đáp án là:'}</b><div class="solution">${groupLabel(v.group)}</div><p>${groupExplanation(v)}</p>`;$('feedback').hidden=false;finishAnswer(ok)}
groupButtons.forEach((b,i)=>b.onclick=()=>{if(!answered&&queue[index]?.form==='group')showGroupSolution(queue[index].v.group===i+1)});
$('end').onclick=finishSession;$('retry').onclick=()=>begin(shuffle([...wrong]));$('new-session').onclick=()=>{$('results').hidden=true;$('setup').hidden=false;updateSetup();$('setup').scrollIntoView({behavior:'smooth',block:'start'})};stats();updateSetup();
